await p.setContent(html,{waitUntil:'networkidle'});
const m=await p.evaluate(()=>{
  const wide=[];document.querySelectorAll('body *').forEach(e=>{const r=e.getBoundingClientRect();if(r.right>document.documentElement.clientWidth+1&&!e.closest('.tbl'))wide.push(e.tagName+'.'+e.className+':'+Math.round(r.right))});
  return {sw:document.documentElement.scrollWidth,cw:document.documentElement.clientWidth,h:document.documentElement.scrollHeight,
  secbtn:document.querySelectorAll('section.part > h2 button.sel').length,itembtn:document.querySelectorAll('.item button.sel').length,items:document.querySelectorAll('.item').length,
  bg:getComputedStyle(document.body).backgroundColor,fg:getComputedStyle(document.body).color,wide:wide.slice(0,10)}});
console.log(scheme,JSON.stringify(m),errs);
// try a Select click on the first case item and report the selection's start
await p.click('#case-1 > .ih button.sel');
const sel=await p.evaluate(()=>{const t=String(window.getSelection());return [t.length,t.slice(0,80)]});
console.log('case-1 select',JSON.stringify(sel));
await p.click('#numbers h2 button.sel');
const sel2=await p.evaluate(()=>{const t=String(window.getSelection());return [t.length,t.slice(-120)]});
console.log('numbers select',JSON.stringify(sel2));
// the sections that the last update changed: an item's Select, and the section's Select, which must stop before its references
await p.click('#test-w5 > .ih button.sel');
const sel3=await p.evaluate(()=>{const t=String(window.getSelection());return [t.length,t.slice(0,60),t.slice(-60)]});
