await p.click('#test h2 button.sel');
const sel4=await p.evaluate(()=>{const t=String(window.getSelection());return [t.length,t.slice(-120)]});
console.log('test select',JSON.stringify(sel4));
if (scheme==='light') {
  const y=await p.evaluate(()=>{const e=document.querySelector('#test');return Math.round(e.getBoundingClientRect().top+scrollY)});
