} else {
  const y=await p.evaluate(()=>{const e=document.querySelector('#checks-f43');return Math.round(e.getBoundingClientRect().top+scrollY)});
  await p.screenshot({path:'shot-dark.png',fullPage:true,clip:{x:0,y:y-20,width:400,height:1700}});
}
await p.close();}
await b.close()})();

